{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Moxifloxacin, a fluoroquinolone carboxylic acid with high polarity and ionizable groups, has an absolute oral bioavailability of 91.8% in humans, demonstrating that carboxylic acid-containing heteroaromatic drugs can be well absorbed despite physicochemical liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Cilomilast, a carboxylic acid-containing drug, is almost completely bioavailable (96%) in humans after oral administration, supporting high oral bioavailability for acidic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Norfloxacin, a structurally related quinolone carboxylic acid with a basic amine and high TPSA, has an oral bioavailability of 30–40% in humans, still well above the 20% threshold and indicating that even less favorable acidic quinolone-like molecules meet the high-F criterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ketanserin, a moderately bioavailable heteroaromatic drug with an absolute bioavailability of about 50% in humans, supports the high-F classification for complex aromatic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Rufinamide, a heteroaromatic drug with an absolute bioavailability of approximately 70–85% in humans, supports high oral bioavailability for complex heteroaromatic structures.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues, including carboxylic acid-containing quinolones/fluoroquinolones and other heteroaromatic drugs, show absolute oral bioavailability above 20% (range approximately 30–96%), strongly supporting a high-F prediction for the query despite its unfavorable physicochemical prior.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query molecule.",
    "Formulation-dependent absorption and possible efflux/metabolism of the query are not directly measured, though analogues indicate the 20% threshold is still met."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

